CREATE TABLE IF NOT EXISTS "device_push_tokens" (
  "id" serial PRIMARY KEY NOT NULL,
  "merchant_id" varchar(64) NOT NULL,
  "user_id" integer NOT NULL,
  "token" text NOT NULL,
  "platform" varchar(8) NOT NULL DEFAULT 'fcm',
  "device_id" varchar(128),
  "app_version" varchar(32),
  "is_active" boolean NOT NULL DEFAULT true,
  "created_at" timestamp DEFAULT now() NOT NULL,
  "updated_at" timestamp DEFAULT now() NOT NULL
);

CREATE INDEX IF NOT EXISTS "push_tokens_merchant_idx" ON "device_push_tokens" ("merchant_id");
CREATE INDEX IF NOT EXISTS "push_tokens_user_idx" ON "device_push_tokens" ("user_id");
CREATE INDEX IF NOT EXISTS "push_tokens_token_idx" ON "device_push_tokens" ("token");
CREATE UNIQUE INDEX IF NOT EXISTS "push_tokens_device_unique" ON "device_push_tokens" ("user_id", "device_id");

